mapper.sql:
WHERE i.information_type = 'JOB'

    AND (
        LOCATE(#{criteria.keyword}, i.title) > 0
        OR LOCATE(#{criteria.keyword}, j.company_name) > 0
        OR LOCATE(#{criteria.keyword}, i.content) > 0
    )


    AND LOCATE(#{criteria.company}, j.company_name) > 0


    AND j.city_name = #{criteria.city}


    AND j.salary_max_monthly_yuan IS NOT NULL
    AND j.salary_max_monthly_yuan >= #{criteria.salaryMin}


    AND j.salary_min_monthly_yuan IS NOT NULL
    AND j.salary_min_monthly_yuan <= #{criteria.salaryMax}


    AND i.source = #{criteria.source}


    AND j.job_status = #{criteria.jobStatus}


    AND j.remote_type = #{criteria.remoteType}
